"$transcriptPath = "c:\Users\Agent\.gemini\antigravity\brain\1273880e-7300-44ee-aa09-3900b3d638f4\.system_generated\logs\transcript.jsonl"
$lines = Get-Content -Path $transcriptPath

for ($i = $lines.Length - 1; $i -ge 0; $i--) {
    $line = $lines[$i]
    if ($line -match "TOOL_RESPONSE" -and $line -match "multi_replace_file_content" -and $line -match "MUTE DEFAULT FOOTSTEPS") {
        $json = $line | ConvertFrom-Json
        $output = $json.content

        $startIndex = $output.IndexOf("[diff_block_start]")
        $endIndex = $output.IndexOf("[diff_block_end]")

        if ($startIndex -ne -1 -and $endIndex -ne -1) {
            $diffText = $output.Substring($startIndex + 18, $endIndex - ($startIndex + 18))
            $diffLines = $diffText -split "`n"
            $recoveredLines = @()
            foreach ($dl in $diffLines) {
                if ($dl.StartsWith("-")) {
                    $recoveredLines += $dl.Substring(1)
                }
            }
            $recoveredLines | Set-Content -Path "c:\Users\Agent\Downloads\WHEELS-main\missing_block.lua"
            Write-Host "Recovered block successfully!"
            exit
        }
    }
}
